        "Иран": ["Iran", "Іран", "Irán", "伊朗", "ईरान", "إيران", "Iran", "ইরান", "Irã", "ایران", "Iran", "Iran", "イラン", "इराण", "ఇరాన్", "İran", "ஈரான்", "Iran", "이란"],
        "Мьянма": ["Myanmar", "М'янма", "Myanmar", "缅甸", "म्यांमार", "ميانمار", "Myanmar", "মিয়ানমার", "Mianmar", "میانمار", "Myanmar", "Myanmar", "ミャンマー", "म्यानमार", "మయన్మార్", "Myanmar", "மியான்மர்", "Myanmar", "미얀마"],
